-- ============================================================================
-- Schema-Drift-Baseline — auto-generated by Claude (2026-06-06)
-- ----------------------------------------------------------------------------
-- Gleicht das Production-Schema (gyqujitkvymlmgroovch) mit den Migrationen ab.
-- Über Monate wurden Schema-Änderungen direkt auf Prod gemacht, die nie als
-- Migration versioniert wurden. Fresh-Replays auf Supabase-Preview-Branches
-- scheiterten deshalb (z.B. 20260601120000_marketplace_comments referenziert
-- marketplace_listings.user_id, das in keiner Migration deklariert war).
--
-- Diese Migration ist vollständig idempotent:
--   • Auf Production = no-op (alle Spalten/Tabellen existieren bereits).
--   • Auf Preview / Fresh = fügt fehlende Spalten und Tabellen nachträglich
--     hinzu, bevor spätere Migrationen sie referenzieren.
--
-- Constraints / RLS / Policies werden bewusst NICHT versucht — nur Spalten
-- und ggf. komplett fehlende Tabellen. Spätere Migrationen können beliebige
-- Indizes/Policies darüber legen.
-- ============================================================================

-- pgcrypto + uuid-ossp werden für gen_random_uuid() / uuid_generate_v4() benötigt.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

