  content text NOT NULL,
  type text NOT NULL DEFAULT 'text'::text,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- livestream_polls
CREATE TABLE IF NOT EXISTS public.livestream_polls (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  room_id uuid REFERENCES public.live_rooms(id) ON DELETE CASCADE NOT NULL,
  question text NOT NULL,
  options jsonb NOT NULL DEFAULT '[]'::jsonb,
  closes_at timestamptz NOT NULL DEFAULT (now() + '00:01:00'::interval),
  created_at timestamptz NOT NULL DEFAULT now()
);

-- lost_pets
CREATE TABLE IF NOT EXISTS public.lost_pets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL,
  pet_name text NOT NULL,
  species text NOT NULL,
  breed text,
  description text,
  image_urls text[] DEFAULT '{}'::text[],
